package com.fitnutri.backend.submission;

import com.fitnutri.backend.common.*;
import com.fitnutri.backend.records.*;
import com.fitnutri.backend.submission.SubmissionReceiptResponse.RecordIdentity;
import com.fitnutri.backend.support.PostgresIntegrationSupport;
import com.fitnutri.backend.user.*;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import static org.junit.jupiter.api.Assertions.*;

class SubmissionServiceIntegrationTest extends PostgresIntegrationSupport {
    @Autowired SubmissionService service;@Autowired CanonicalSubmissionHasher hasher;@Autowired UserRepository users;@Autowired FoodRecordRepository foods;@Autowired SubmissionReceiptRepository receipts;@Autowired PlatformTransactionManager transactions;
    private User owner(){var u=new User();u.setEmail("submission-"+UUID.randomUUID()+"@example.test");u.setDisplayName("Synthetic test");u.setPasswordHash("not-a-login-credential");return users.saveAndFlush(u);}
    private CanonicalSubmissionHasher.Submission input(UUID submission,List<UUID> clients,String grams){return hasher.food(submission,LocalDate.of(2020,1,1),"Australia/Sydney",RecordSource.MANUAL,clients.stream().map(id->new CanonicalSubmissionHasher.FoodItem(id,101L,new BigDecimal(grams),MealType.LUNCH)).toList());}
    // Infrastructure transaction fixtures deliberately use honest legacy quality, not a fictitious verified food source.
    private FoodRecord row(User u,UUID client){var r=new FoodRecord();r.setUser(u);r.setFoodName("Synthetic receipt test");r.setQuantityGramsSnapshot(new BigDecimal("100.000"));r.setMealType(MealType.LUNCH);r.setSource(RecordSource.MANUAL);r.setRecordedAt(Instant.parse("2020-01-01T00:00:00Z"));r.setRecordDate(LocalDate.of(2020,1,1));r.setClientEntryId(client);return r;}
    private RecordIdentity create(User u,UUID client){var r=foods.saveAndFlush(row(u,client));return new RecordIdentity(r.getId().toString(),client,r.getRecordDate(),r.getVersion());}
    @Test void concurrentSameKeyUsesTwoTransactionsButCreatesOnlyOnce() throws Exception {
        var u=owner();var client=UUID.randomUUID();var request=input(UUID.randomUUID(),List.of(client),"100");var start=new CountDownLatch(1);var writes=new AtomicInteger();
        try(var pool=Executors.newFixedThreadPool(2)){Callable<SubmissionReceiptResponse> work=()->{start.await();return service.withSubmission(u.getId(),request,user->{writes.incrementAndGet();return List.of(create(user,client));});};var a=pool.submit(work);var b=pool.submit(work);start.countDown();var first=a.get(15,TimeUnit.SECONDS);var second=b.get(15,TimeUnit.SECONDS);assertNotEquals(first.replayed(),second.replayed());assertEquals(first.records(),second.records());assertEquals(first.committedAt(),second.committedAt());assertEquals(1,writes.get());assertEquals(1,foods.findByUserIdOrderByRecordedAtDesc(u.getId()).size());}
    }
    @Test void changedPayloadAndOperationConflictBeforeCallback(){var u=owner();var id=UUID.randomUUID();var client=UUID.randomUUID();service.withSubmission(u.getId(),input(id,List.of(client),"100"),user->List.of(create(user,client)));assertEquals("IDEMPOTENCY_CONFLICT",assertThrows(BusinessException.class,()->service.withSubmission(u.getId(),input(id,List.of(client),"101"),user->{fail("must not create changed replay");return List.of();})).code());var exercise=hasher.exercise(id,LocalDate.of(2020,1,1),"Australia/Sydney",RecordSource.MANUAL,client,1L,BigDecimal.TEN,"reviewed");assertEquals("IDEMPOTENCY_CONFLICT",assertThrows(BusinessException.class,()->service.withSubmission(u.getId(),exercise,user->{fail("must not change operation");return List.of();})).code());}
    @Test void secondRecordConstraintFailureRollsBackFirstRecordAndPendingReceipt(){var u=owner();var first=UUID.randomUUID();var second=UUID.randomUUID();var request=input(UUID.randomUUID(),List.of(first,second),"100");assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->service.withSubmission(u.getId(),request,user->{var proof=create(user,first);var bad=row(user,second);bad.setQuantityGramsSnapshot(null);foods.saveAndFlush(bad);return List.of(proof);}));assertTrue(foods.findByUserIdOrderByRecordedAtDesc(u.getId()).isEmpty());assertTrue(receipts.findByUserIdAndSubmissionId(u.getId(),request.submissionId()).isEmpty());}
    @Test void incompleteProofAfterFlushedRecordRollsBackEverything(){var u=owner();var client=UUID.randomUUID();var request=input(UUID.randomUUID(),List.of(client),"100");assertThrows(IllegalStateException.class,()->service.withSubmission(u.getId(),request,user->{create(user,client);return List.of();}));assertTrue(foods.findByUserIdOrderByRecordedAtDesc(u.getId()).isEmpty());assertTrue(receipts.findByUserIdAndSubmissionId(u.getId(),request.submissionId()).isEmpty());}
    @Test void deletionDoesNotDestroyCreationProofAndReplayNeverResurrectsIt(){var u=owner();var client=UUID.randomUUID();var request=input(UUID.randomUUID(),List.of(client),"100");var original=service.withSubmission(u.getId(),request,user->List.of(create(user,client)));var row=foods.findById(Long.valueOf(original.records().getFirst().id())).orElseThrow();row.setDeletedAt(Instant.now());foods.saveAndFlush(row);var replay=service.withSubmission(u.getId(),request,user->{fail("replay must not rerun business rules or create");return List.of();});assertTrue(replay.replayed());assertEquals(original.records(),replay.records());assertEquals(0,replay.records().getFirst().versionAtCreation());assertTrue(foods.findByUserIdOrderByRecordedAtDesc(u.getId()).isEmpty());assertNotNull(foods.findById(row.getId()).orElseThrow().getDeletedAt());assertEquals(original.records(),service.findReceipt(u.getId(),request.submissionId()).records());assertEquals("CLIENT_ENTRY_CONFLICT",assertThrows(BusinessException.class,()->service.withSubmission(u.getId(),input(UUID.randomUUID(),List.of(client),"100"),user->List.of(create(user,client)))).code());}
    @Test void duplicateClientIdentityAndCrossSubmissionReuseAreRejectedRatherThanSkipped(){var u=owner();var client=UUID.randomUUID();var duplicate=input(UUID.randomUUID(),List.of(client,client),"100");assertEquals("VALIDATION_ERROR",assertThrows(BusinessException.class,()->service.withSubmission(u.getId(),duplicate,user->{fail("duplicate rejected before work");return List.of();})).code());assertTrue(receipts.findByUserIdAndSubmissionId(u.getId(),duplicate.submissionId()).isEmpty());service.withSubmission(u.getId(),input(UUID.randomUUID(),List.of(client),"100"),user->List.of(create(user,client)));var reuse=input(UUID.randomUUID(),List.of(client),"100");assertEquals("CLIENT_ENTRY_CONFLICT",assertThrows(BusinessException.class,()->service.withSubmission(u.getId(),reuse,user->{fail("reuse must not create");return List.of();})).code());assertTrue(receipts.findByUserIdAndSubmissionId(u.getId(),reuse.submissionId()).isEmpty());var crossKind=hasher.exercise(UUID.randomUUID(),LocalDate.of(2020,1,1),"Australia/Sydney",RecordSource.MANUAL,client,1L,BigDecimal.TEN,"reviewed");assertEquals("CLIENT_ENTRY_CONFLICT",assertThrows(BusinessException.class,()->service.withSubmission(u.getId(),crossKind,user->{fail("cross-kind entry identity must remain distinct");return List.of();})).code());}
    @Test void pendingReceiptIsNotVisibleAnd404DoesNotPreventOriginalRequestLaterCommitting() throws Exception {
        var u=owner();var client=UUID.randomUUID();var request=input(UUID.randomUUID(),List.of(client),"100");var pending=new CountDownLatch(1);var release=new CountDownLatch(1);
        try(var pool=Executors.newSingleThreadExecutor()){var future=pool.submit(()->service.withSubmission(u.getId(),request,user->{pending.countDown();try{if(!release.await(10,TimeUnit.SECONDS))throw new IllegalStateException("test release timed out");}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException(e);}return List.of(create(user,client));}));try{assertTrue(pending.await(10,TimeUnit.SECONDS));assertEquals("NOT_FOUND",assertThrows(BusinessException.class,()->service.findReceipt(u.getId(),request.submissionId())).code());}finally{release.countDown();}assertFalse(future.get(15,TimeUnit.SECONDS).replayed());assertTrue(service.findReceipt(u.getId(),request.submissionId()).replayed());}
    }
    @Test void receiptLookupIsOwnerScopedAndAccountIsRecheckedBeforeReplay(){var u=owner();var client=UUID.randomUUID();var request=input(UUID.randomUUID(),List.of(client),"100");service.withSubmission(u.getId(),request,user->List.of(create(user,client)));assertEquals("NOT_FOUND",assertThrows(BusinessException.class,()->service.findReceipt(owner().getId(),request.submissionId())).code());u=users.findById(u.getId()).orElseThrow();u.setEnabled(false);users.saveAndFlush(u);Long id=u.getId();assertEquals("UNAUTHENTICATED",assertThrows(BusinessException.class,()->service.withSubmission(id,request,user->{fail("inactive cannot replay");return List.of();})).code());}
    @Test void joiningAnOuterTransactionIsRejectedToAvoidReturningUncommittedProof(){var u=owner();var request=input(UUID.randomUUID(),List.of(UUID.randomUUID()),"100");assertThrows(IllegalStateException.class,()->new TransactionTemplate(transactions).execute(status->service.withSubmission(u.getId(),request,user->List.of())));}
}
